/**
 * Expo config plugin: signs release builds with your own upload key when one is configured, and
 * falls back to the debug key (fine for testers, not for Play) when it isn't.
 *
 * android/ is generated by prebuild and git-ignored, so the signing setup lives here and is
 * re-applied on every prebuild. No secret is ever written into the generated Gradle file: Gradle
 * reads them at build time from credentials/keystore.properties (git-ignored) or env variables.
 *
 *   credentials/keystore.properties          or env variables
 *   storeFile=credentials/upload.jks          ARROWZING_STORE_FILE
 *   storePassword=...                         ARROWZING_STORE_PASSWORD
 *   keyAlias=upload                           ARROWZING_KEY_ALIAS
 *   keyPassword=...                           ARROWZING_KEY_PASSWORD
 *
 * storeFile is relative to the project root.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// @withReleaseSigning';

const LOADER = `${MARKER}
def releaseSigningProps = new Properties()
def releaseSigningFile = new File(rootDir, '../credentials/keystore.properties')
if (releaseSigningFile.exists()) releaseSigningFile.withInputStream { releaseSigningProps.load(it) }
def releaseSigning = { String key, String env -> releaseSigningProps.getProperty(key) ?: System.getenv(env) }
def releaseStoreFile = releaseSigning('storeFile', 'ARROWZING_STORE_FILE')
def hasReleaseSigning = releaseStoreFile && new File(rootDir, "../\${releaseStoreFile}").exists()
`;

const RELEASE_CONFIG = `
        if (hasReleaseSigning) {
            release {
                storeFile new File(rootDir, "../\${releaseStoreFile}")
                storePassword releaseSigning('storePassword', 'ARROWZING_STORE_PASSWORD')
                keyAlias releaseSigning('keyAlias', 'ARROWZING_KEY_ALIAS')
                keyPassword releaseSigning('keyPassword', 'ARROWZING_KEY_PASSWORD')
            }
        }`;

function apply(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  const steps = [
    // Loader goes just before the android block.
    [/\nandroid \{/, `\n${LOADER}\nandroid {`],
    // The release build type uses it when present (before the config below adds a second "release {").
    [
      /(release \{[^}]*?)signingConfig signingConfigs\.debug/,
      '$1signingConfig hasReleaseSigning ? signingConfigs.release : signingConfigs.debug',
    ],
    // The release signing config sits next to the debug one.
    [/(signingConfigs \{\s*\n\s*debug \{[^}]*\})/, `$1${RELEASE_CONFIG}`],
  ];
  for (const [pattern, replacement] of steps) {
    if (!pattern.test(gradle)) throw new Error(`withReleaseSigning: android/app/build.gradle no longer matches ${pattern}`);
    gradle = gradle.replace(pattern, replacement);
  }
  return gradle;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = apply(mod.modResults.contents);
    return mod;
  });
};
